 1215 Código Civil: fuente legada exige comunicación fehaciente; condiciones y alcance del Exp 01326-2019-0 requieren fuente jurídica vigente. Desarrollo permitido; applicability_v1 UNRESOLVED se conserva, no inferir pantalla, ámbito de cobranza ni consumidor adicional. Gate de gobierno no equivale a resolver aplicabilidad. Binding runtime pendiente; no modifica IG, fuentes oficiales ni legadas.","efecto":"BLOQUEAR","autoridad":"LEG-PRODUCTO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/380","solicitante":"Cristhian / Claude S22-AW"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"aw_assignment_legal_copy_release"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"aw_assignment_claim_no_notice_no_pay"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"aw_assignment_claim_original_contact_always_valid"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"aw_assignment_claim_advance_consent_always_valid"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"aw_assignment_source_unverified"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"aw_assignment_applicability_assumed"},"der":{"lit":true}}}},"pruebas":[{"entrada":{"aw_assignment_legal_copy_release":true,"aw_assignment_claim_no_notice_no_pay":false,"aw_assignment_claim_original_contact_always_valid":false,"aw_assignment_claim_advance_consent_always_valid":false,"aw_assignment_source_unverified":false,"aw_assignment_applicability_assumed":false},"esperado":false,"casuistica":"NO_SE_CUMPLE"},{"entrada":{"aw_assignment_legal_copy_release":true,"aw_assignment_claim_no_notice_no_pay":true,"aw_assignment_claim_original_contact_always_valid":false,"aw_assignment_claim_advance_consent_always_valid":false,"aw_assignment_source_unverified":false,"aw_assignment_applicability_assumed":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"aw_assignment_legal_copy_release":true,"aw_assignment_claim_no_notice_no_pay":